import html
import re
from urllib.parse import urlsplit

from .net import canonical


def safe_href(url):
    # API evidence may have query parameters generated by the detector.
    if not canonical(url) or re.search(r'[\s<>"()\\]', url):
        return ""
    if urlsplit(url).query and urlsplit(url).hostname != "api.gopluslabs.io":
        return canonical(url)
    return url


def link(title, url):
    href = safe_href(url)
    label = html.escape(str(title))
    return f'<a rel="noreferrer" href="{html.escape(href, quote=True)}">{label}</a>' if href else label


def md(value):
    return re.sub(r"([\\\[\]*_\x60|#!~])", r"\\\1", html.escape(" ".join(str(value).split())))


def md_link(title, url):
    href = safe_href(url)
    return f"[{md(title)}](<{href}>)" if href else md(title)


def build_markdown(p):
    lines = ["# Crypto Intelligence v2", "", f"**{p['time_utc']} UTC** · Бюджет €0 · Заработано $0",
             "", "## TOP-5 новых возможностей", ""]
    if not p["top"]:
        lines.append("Новых публикаций, прошедших отбор, в этой проверке нет.")
    for item in p["top"]:
        lines.extend([f"- **{md_link(item['title'], item['url'])}** — {md(item['source'])}",
                      "  - " + " · ".join(md(k) + " — " + md(v) for k, v in item["terms"].items()),
                      "  - " + md(item["risk"]["status"]) + " · " + md(item["risk"]["reasons"][0]),
                      "  - Отбор — " + md(item["selection"])])
    incomplete = [k for k, v in p["health"].items() if v.startswith(("HTTP ", "Нет данных", "URLError", "TimeoutError", "ValueError"))]
    if incomplete:
        lines += ["", "Частичные данные — " + ", ".join(md(k) for k in incomplete) + "."]
    lines += ["", "Условия приведены по публикациям. Фактический вывод требует отдельной проверки.",
              "", "## Рынок за 24 часа", ""]
    lines.append(" · ".join(md_link(c["symbol"] or c["id"], c["source"]) + " " + price_line(c)
                            for c in p["market"]) or "Котировки недоступны.")
    lines += ["", f"Новых публикаций {len(p['new'])}, всего проверено возможностей {len(p['latest'])}.",
              "Доступность источников, все находки и оценки контрактов — [HTML](LATEST.html) · [JSON](latest.json).", ""]
    return "\n".join(lines)


def price_line(c):
    price = "н/д" if c["usd"] is None else f"\u0024{c['usd']:,.6g}"
    change = "н/д" if c["change24h"] is None else f"{c['change24h']:+.2f}%"
    return f"{price} ({change})"


def risk_block(risk):
    reasons = "".join("<li>" + html.escape(s) + "</li>" for s in risk["reasons"])
    sources = " · ".join(link(k, v) for k, v in risk["sources"].items())
    return "<strong>" + html.escape(risk["status"]) + "</strong><ul>" + reasons + "</ul>" + sources


def build_html(p):
    parts = ['<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">',
             '<title>Crypto Intelligence v2</title><style>body{font:16px/1.55 system-ui;color:#172936;background:#f6f8fa;margin:2rem auto;max-width:62rem;padding:0 1rem}article,section{background:white;border:1px solid #cdd6dc;padding:1rem;margin:1rem 0;border-radius:.5rem}a{color:#17528a}code{overflow-wrap:anywhere}</style>',
             "<main><h1>Crypto Intelligence v2</h1>", html.escape(p["time_utc"]) + " UTC · Заработано $0",
             "<h2>Рынок и публикации</h2><p>Изменение цены за 24 часа. Сопоставление с публикациями за сегодня и вчера по UTC. Причинная связь не установлена.</p>"]
    for c in p["market"]:
        parts.append("<article>" + link(c["name"], c["source"]) + " · " + price_line(c))
        for n in c.get("news", []):
            parts.append("<p>" + link(n["title"], n["url"]) + "</p>")
        if not c.get("news"):
            parts.append("<p>Совпадающих официальных публикаций в выборке нет.</p>")
        parts.append("</article>")
    parts.append("<h2>Все возможности</h2>")
    new_urls = {x["url"] for x in p["new"]}
    items = p["latest"] or p["new"]
    for item in items:
        parts.append("<article><h3>" + link(item["title"], item["url"]) + "</h3>")
        parts.append("<p>" + ("Новая" if item["url"] in new_urls else "Ранее встречалась") + " · " +
                     html.escape(item["source"] + " · " + item["published"]) + "</p>")
        terms = item.get("terms", {})
        parts.append("<p>" + " · ".join(html.escape(k + " — " + v) for k, v in terms.items()) + "</p>")
        if "risk" in item:
            parts.append(risk_block(item["risk"]))
            parts.append("<p>" + html.escape(item["selection"]) + "</p>")
            if not item["eligible"]:
                parts.append("<p>Исключена из отбора — " + html.escape(", ".join(item["exclusions"])) + "</p>")
            parts.append("<p>" + " · ".join(link(k, v) for k, v in item["sources"].items()) + "</p>")
            if item["mentions"]:
                parts.append("<p>Совпадающие ссылки — " + html.escape(", ".join(item["mentions"])) + "</p>")
        parts.append("</article>")
    if not items:
        parts.append("<p>Возможностей в доступных источниках не найдено.</p>")
    parts.append("<h2>Проверенные контракты</h2><p>Отсутствие тревожных признаков не гарантирует безопасность.</p>")
    for r in p.get("contracts", []):
        parts.append("<article><code>" + html.escape(r["chain_id"] + ":" + r["address"]) + "</code><p>" + risk_block(r) + "</article>")
    parts.append("<h2>Доступность источников</h2><ul>")
    for k, v in p["health"].items():
        parts.append("<li>" + html.escape(k + " — " + v) + "</li>")
    parts.append("</ul></main></html>")
    return "\n".join(parts)
